import Foundation
import SwiftUI
import NSDesign

/// A dated citation supplied by the app; no legal conclusions are generated by the kit.
public struct DataSource: Equatable, Sendable {
    /// Human-readable source name.
    public let title: String
    /// HTTPS source URL.
    public let url: URL
    /// The date on which the app's source was checked.
    public let checkedAt: Date
    /// Creates a citation, rejecting non-HTTPS or hostless links.
    public init(title: String, url: URL, checkedAt: Date) throws {
        guard url.scheme?.lowercased() == "https", url.host != nil,
              url.user == nil, url.password == nil else { throw SourceError.invalidURL }
        self.title = title; self.url = url; self.checkedAt = checkedAt
    }
}

/// Citation validation errors.
public enum SourceError: Error {
    /// A source requires an HTTPS URL with a host and no embedded credentials.
    case invalidURL
}

/// Displays an external source link and its review date using the viewer's locale.
public struct DataSourceLabel: View {
    private let source: DataSource
    private let dateLabel: String
    /// Creates a source label; apps may localise the date prefix.
    public init(_ source: DataSource, dateLabel: String = "Checked") { self.source = source; self.dateLabel = dateLabel }
    /// The source link opens through the system's URL handler.
    public var body: some View {
        VStack(alignment: .leading, spacing: DesignTokens.small) {
            Link(destination: source.url) { Label(source.title, systemImage: "arrow.up.right.square") }
            Text("\(dateLabel) \(source.checkedAt.formatted(date: .abbreviated, time: .omitted))")
                .foregroundStyle(.secondary)
        }.font(DesignTokens.caption)
    }
}

/// Displays disclaimer text authored and reviewed by the app owner.
public struct DisclaimerView: View {
    private let text: String
    /// Creates a disclaimer without inventing compliance or legal claims.
    public init(_ text: String) { self.text = text }
    /// The explanatory text and information symbol.
    public var body: some View {
        Label(text, systemImage: "info.circle").font(DesignTokens.caption).foregroundStyle(.secondary)
            .fixedSize(horizontal: false, vertical: true)
    }
}
